def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    line = next(c for c in colors if c != bg)
    out = [row[:] for row in grid]

    # Find the fully outlined rectangular region and color its interior.
    candidates = []
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (all(grid[r1][c] == line and grid[r2][c] == line
                            for c in range(c1, c2 + 1)) and
                        all(grid[r][c1] == line and grid[r][c2] == line
                            for r in range(r1, r2 + 1))):
                        candidates.append((r1, r2, c1, c2))

    if candidates:
        r1, r2, c1, c2 = min(candidates, key=lambda box: (box[1]-box[0]) * (box[3]-box[2]))
        for r in range(r1 + 1, r2):
            for c in range(c1 + 1, c2):
                if grid[r][c] == bg:
                    out[r][c] = 4
    return out
